+        assert_eq!(ep.plan, "zai");
+        let bad = |v: Value| endpoint_from_value(&v, "").unwrap_err();
+        assert_eq!(bad(json!("https://x")), "endpoint must be an object {\"base_url\": \"https://...\", \"env_key\": \"<VARIABLE NAME>\", \"timeout_ms\": <milliseconds, optional>}");
