  439: /// `Get-ClaudeInitProblem`: what the init events of a turn prove (evidence first) - `("", "")`
  440: /// when proven or when there is no init (the caller decides).
  441: pub fn init_problem(e: &ClaudeEvents, auth: &str) -> (String, &'static str) {
  442:     if e.init_count == 0 {
  443:         return (String::new(), "");
  444:     }
  445:     if let Some(lack) = e.init_lacks.first() {
  446:         return (
  447:             format!("init event lacks {lack} - the CLI's schema changed; pin the version"),
  448:             "capability",
  449:         );
  450:     }
  451:     let extra: Vec<&String> = e
  452:         .init_tools
  453:         .iter()
  454:         .filter(|t| !CLAUDE_TOOLS.contains(&t.as_str()))
  455:         .collect();
  456:     if !extra.is_empty() {
  457:         return (
  458:             format!(
  459:                 "the init event lists tools outside {}: {} - the turn's read-only capability is not proven",
  460:                 CLAUDE_TOOLS.join(", "),
  461:                 extra
  462:                     .iter()
  463:                     .map(|s| s.as_str())
  464:                     .collect::<Vec<_>>()
  465:                     .join(", ")
  466:             ),
  467:             "permission",
  468:         );
  469:     }
  470:     if !e.init_mcp.is_empty() {
  471:         return (
  472:             format!(
  473:                 "the init event lists MCP server(s) ({}) - a reviewer runs without any",
  474:                 e.init_mcp.join(", ")
  475:             ),
  476:             "permission",
  477:         );
  478:     }
  479:     if let Some(bad) = e.init_modes.iter().find(|m| *m != CLAUDE_PERMISSION_MODE) {
  480:         return (
  481:             format!(
  482:                 "the init event names the permission mode '{}', not {CLAUDE_PERMISSION_MODE}",
  483:                 c3_core::claude::token(Some(&Value::String(bad.clone())))
  484:             ),
  485:             "permission",
  486:         );
  487:     }
  488:     if auth == "endpoint" {
  489:         if e.init_key_sources.iter().any(|k| k == "ANTHROPIC_API_KEY") {
  490:             return ("the init event names apiKeySource ANTHROPIC_API_KEY on an endpoint route - a competing credential reached the child (auth endpoint sends ANTHROPIC_AUTH_TOKEN only)".to_string(), "auth");
  491:         }
  492:         return (String::new(), "");
  493:     }
  494:     if e.init_key_lacks {
  495:         return (
  496:             "init event lacks apiKeySource - the billing proof of this auth mode; pin the CLI version"
  497:                 .to_string(),
  498:             "auth",
  499:         );
  500:     }
  501:     let want = if auth == "api-key" {
  502:         "ANTHROPIC_API_KEY"
  503:     } else {
  504:         "none"
  505:     };
  506:     if let Some(bad) = e.init_key_sources.iter().find(|k| *k != want) {
  507:         let shown = if bad.is_empty() {
  508:             "(none named)".to_string()
  509:         } else {
  510:             c3_core::claude::token(Some(&Value::String(bad.clone())))
  511:         };
  512:         return (
  513:             format!(
  514:                 "the init event names apiKeySource {shown}, not {want} - the turn did not bill {} the roster names (auth {auth})",
  515:                 if auth == "api-key" {
  516:                     "the API key"
  517:                 } else {
  518:                     "the claude.ai subscription"
  519:                 }
  520:             ),
---CHUNK---
  520:             ),
  521:             "auth",
  522:         );
  523:     }
  524:     (String::new(), "")
  525: }
  526: 
  527: /// `Get-ClaudeServedModelProblem` (E12, E13): every init model must be the pinned one (an alias
  528: /// takes an id of its family; `exact` - endpoint - equality only), and every assistant message by
  529: /// the init's id. Class capability.
  530: pub fn served_model_problem(e: &ClaudeEvents, pinned: &str, exact: bool) -> (String, &'static str) {
  531:     if e.init_model.is_empty() {
  532:         return (String::new(), "");
  533:     }
  534:     if !pinned.is_empty() {
  535:         if let Some(drift) = e
  536:             .init_models
  537:             .iter()
  538:             .find(|m| !model_match(pinned, m, exact))
  539:         {
  540:             return (
  541:                 format!("model drift: asked {pinned}, served {drift}"),
  542:                 "capability",
  543:             );
  544:         }
  545:     }
  546:     if let Some(foreign) = e
  547:         .assistant_models
  548:         .iter()
  549:         .find(|m| !model_match(&e.init_model, m, true))
  550:     {
  551:         return (
  552:             format!("a different model authored an assistant message: {foreign}"),
  553:             "capability",
  554:         );
  555:     }
  556:     (String::new(), "")
  557: }
  558: 
  559: /// (D6) The wording of a usage limit (`$script:ClaudeQuotaRe`).
  560: pub const QUOTA_RE: &str = r"(?i)usage limit|limit reached|hit your (?:usage |session |weekly )?limit|rate[ _]limit|weekly limit|session limit|quota|too many requests|\b429\b|credit balance is too low|overage";
  561: /// (D6, E4) The wording of a missing sign-in or a rejected credential (`$script:ClaudeAuthRe`).
  562: pub const AUTH_RE: &str = r"(?i)not logged in|please run /login|invalid api key|oauth token (?:has )?(?:expired|revoked)|authentication[ _]error|failed to authenticate|api error: 40[13]\b|\b401\b|unauthori[sz]ed";
  563: 
  564: /// The turn's options as the rules read them (`New-EngineTurnOptions` / `-Turn`).
  565: #[derive(Debug, Clone, Default)]
  566: pub struct ClaudeTurnOpts {
  567:     /// `new` | `resume` | `fork` | `denial-retry` | `format-repair` | `timeout-continue`.
  568:     pub mode: String,
  569:     /// The thread the turn continues (`--resume`); `""` for a new one.
  570:     pub thread: String,
  571:     /// The minted id of a new thread (`--session-id`).
  572:     pub new_thread: String,
  573:     /// The pinned model (the roster's, or the resolved id).
  574:     pub model: String,
  575:     pub auth: String,
  576: }
  577: 
  578: /// One claude turn's outcome (`Get-ClaudeTurnOutcome`'s result).
  579: #[derive(Debug, Clone, Default)]
  580: pub struct ClaudeTurn {
  581:     pub ok: bool,
  582:     /// `usable reply` or `failed: <why>` (with `pre`: the pre text unless the proof failed).
  583:     pub outcome: String,
  584:     /// The forced class (`''` = classify the texts).
  585:     pub class: String,
  586:     /// The failure evidence, best first.
  587:     pub texts: Vec<String>,
  588:     pub thread: String,
  589:     pub thread_candidate: String,
  590:     pub reply: String,
  591:     pub structured: bool,
  592:     pub denied_empty: bool,
  593:     pub denial_line: String,
  594:     pub warnings: Vec<String>,
  595:     /// (D4) The model the init event resolved (`[1m]` kept when the pin had it).
  596:     pub model_resolved: String,
  597:     pub other_models: Vec<String>,
  598:     /// (E12) The init or model proof failed: no continuation may resume the session.
  599:     pub proof_problem: String,
  600:     /// (E15) A rejecting rate_limit_event beside a successful result: the quota text a failed
  601:     /// turn would carry (the route is marked with it).
  602:     pub quota_mark: String,
  603: }
  604: 
  605: fn fmt_utc(d: &DateTime<Utc>) -> String {
  606:     d.format("%Y-%m-%dT%H:%M:%SZ").to_string()
  607: }
  608: 
  609: /// `Get-ClaudeTurnOutcome`: the failure rules of one claude turn. `pre`: a failure the bridge
  610: /// already knows (a kill) - it wins over everything but the proof of the turn's init and model
  611: /// (E12). `expect_thread` / `expect_model` as the plugin's.
  612: pub fn claude_turn_outcome(
  613:     e: &ClaudeEvents,
  614:     exit_code: i32,
  615:     stderr_text: &str,
  616:     pre: &str,
  617:     expect_thread: &str,
  618:     expect_model: &str,
  619:     turn: &ClaudeTurnOpts,
  620: ) -> ClaudeTurn {
  621:     let mut o = ClaudeTurn::default();
  622:     let lines: Vec<String> = stderr_text
  623:         .split('\n')
  624:         .map(|l| l.trim().to_string())
  625:         .filter(|l| !l.is_empty())
  626:         .collect();
  627:     let stderr_tail = lines.last().cloned().unwrap_or_default();
  628:     let auth = if CLAUDE_AUTH_MODES.contains(&turn.auth.as_str()) {
  629:         turn.auth.as_str()
  630:     } else {
  631:         "subscription"
  632:     };
  633:     let exact = auth == "endpoint";
  634:     let pinned = if !expect_model.is_empty() {
  635:         expect_model.to_string()
  636:     } else {
  637:         turn.model.clone()
  638:     };
  639:     let fork_of = if turn.mode == "fork" && !turn.thread.is_empty() {
  640:         turn.thread.clone()
  641:     } else {
  642:         String::new()
  643:     };
  644:     let mut expect = expect_thread.to_string();
  645:     if expect.is_empty() && !turn.thread.is_empty() && fork_of.is_empty() {
  646:         expect = turn.thread.clone();
  647:     }
  648:     if expect.is_empty() && turn.thread.is_empty() && !turn.new_thread.is_empty() {
  649:         expect = turn.new_thread.clone();
  650:     }
  651:     let res_id = e.thread.clone();
  652:     let init_id = e.init_thread.clone();
  653:     let ok_id = |id: &str| -> bool {
  654:         is_uuid(id) && (expect.is_empty() || id == expect) && (fork_of.is_empty() || id != fork_of)
  655:     };
  656:     let candidate_of = |id: &str| -> String {
  657:         if is_uuid(id) && (fork_of.is_empty() || id != fork_of) {
  658:             id.to_string()
  659:         } else {
  660:             String::new()
  661:         }
  662:     };
  663:     o.structured = e.has_structured;
  664:     o.reply = if e.has_structured {
  665:         e.structured_json.clone()
  666:     } else if !e.is_error {
  667:         e.response.clone()
  668:     } else {
  669:         String::new()
  670:     };
  671:     // (D6) the quota evidence: a rejecting rate_limit_event, else the limit wording of the
  672:     // result's text or stderr; its reset time (the event's, else a "|<unix time>" in the text)
  673:     let err_text = e.error.clone();
  674:     let quota_re = re(QUOTA_RE);
  675:     let auth_re = re(AUTH_RE);
  676:     let mut quota_text = String::new();
  677:     let mut reset_at = e.rate_limit_reset;
  678:     if e.rate_limit_rejected {
  679:         quota_text = format!(
  680:             "usage limit reached (claude rate_limit_event {}{})",
  681:             e.rate_limit_status,
  682:             if e.rate_limit_type.is_empty() {
  683:                 String::new()
  684:             } else {
  685:                 format!(", {}", e.rate_limit_type)
  686:             }
  687:         );
  688:     } else if !err_text.is_empty() && quota_re.is_match(&err_text) {
  689:         quota_text = format!("usage limit: {}", one_line(&err_text));
  690:     } else if let Some(ql) = lines.iter().find(|l| quota_re.is_match(l)) {
  691:         quota_text = format!("usage limit: {}", one_line(ql));
  692:     }
  693:     if !quota_text.is_empty() && reset_at.is_none() {
  694:         if let Some(c) = re(r"\|(?P<t>[0-9]{10,13})\b").captures(&err_text) {
  695:             reset_at = reset_time(&Value::String(c["t"].to_string()));
  696:         }
  697:     }
  698:     if !quota_text.is_empty() {
  699:         if let Some(r) = reset_at {
  700:             quota_text.push_str(&format!("; resets at {}", fmt_utc(&r)));
  701:         }
  702:     }
  703:     let mut auth_text = String::new();
  704:     if quota_text.is_empty() {
  705:         if !err_text.is_empty() && auth_re.is_match(&err_text) {
  706:             auth_text = one_line(&err_text);
  707:         } else if let Some(al) = lines.iter().find(|l| auth_re.is_match(l)) {
  708:             auth_text = one_line(al);
  709:         }
  710:     }
  711:     let evidence_class = if !quota_text.is_empty() {
  712:         "quota"
  713:     } else if !auth_text.is_empty() {
  714:         "auth"
  715:     } else {
  716:         ""
  717:     };
  718:     let fail = |o: &mut ClaudeTurn, why: &str, class: &str, texts: &[&str]| {
  719:         o.ok = false;
  720:         o.outcome = format!("failed: {why}");
  721:         o.class = class.to_string();
  722:         let mut all: Vec<String> = texts
  723:             .iter()
  724:             .filter(|t| !t.is_empty())
  725:             .map(|t| t.to_string())
  726:             .collect();
  727:         if !why.is_empty() {
  728:             all.push(why.to_string());
  729:         }
  730:         o.texts = all;
  731:     };
  732:     let detail = if !err_text.trim().is_empty() {
  733:         err_text.clone()
  734:     } else {
  735:         stderr_tail.clone()
  736:     };
  737:     if !pre.is_empty() {
  738:         // (E12) a killed turn's init and model are judged too
  739:         let (mut problem, mut class) = init_problem(e, auth);
  740:         if problem.is_empty() {
  741:             (problem, class) = served_model_problem(e, &pinned, exact);
  742:         }
  743:         if !problem.is_empty() {
  744:             let stopped = one_line(&re(r"^failed:\s*").replace(pre, ""));
  745:             fail(
  746:                 &mut o,
  758:         } else {
  759:             "quota".into()
  760:         };
  761:         let pre_tail = re(r"^failed:\s*").replace(pre, "").to_string();
  762:         o.texts = [
  763:             quota_text.as_str(),
  764:             err_text.as_str(),
  765:             stderr_tail.as_str(),
  766:             pre_tail.as_str(),
  767:         ]
  768:         .iter()
  769:         .filter(|t| !t.is_empty())
  770:         .map(|t| t.to_string())
  771:         .collect();
  772:         o.thread_candidate = candidate_of(if res_id.is_empty() { &init_id } else { &res_id });
  773:         if !o.thread_candidate.is_empty() && !expect.is_empty() && o.thread_candidate != expect {
  774:             o.thread_candidate = String::new();
  775:         }
  776:         // (D4) a killed turn's init already resolved the model: the continuation sends that id
  777:         let served = e.init_model.clone();
  778:         if !served.is_empty() && (pinned.is_empty() || model_match(&pinned, &served, exact)) {
  779:             o.model_resolved = served.clone();
  780:             if re(r"(?i)\[1m\]$").is_match(&pinned) && !re(r"(?i)\[1m\]$").is_match(&served) {
  781:                 o.model_resolved.push_str("[1m]");
  782:             }
  783:         }
  784:         return o;
  785:     }
  786:     let (problem, class) = init_problem(e, auth);
  787:     if !problem.is_empty() {
  788:         fail(&mut o, &problem, class, &[]);
  789:         o.proof_problem = problem;
  790:         o.thread_candidate = candidate_of(if res_id.is_empty() { &init_id } else { &res_id });
  791:         return o;
  792:     }
  793:     if exit_code != 0 {
  794:         let why = format!(
  795:             "claude exit {exit_code}{}",
  796:             if detail.is_empty() {
  797:                 String::new()
  798:             } else {
  799:                 format!(" - {}", one_line(&detail))
  800:             }
  801:         );
  802:         fail(
  803:             &mut o,
  804:             &why,
  805:             evidence_class,
  806:             &[&quota_text, &auth_text, &err_text, &stderr_tail],
  807:         );
  808:         if ok_id(&res_id) {
  809:             o.thread = res_id.clone();
  810:         } else {
  811:             o.thread_candidate = candidate_of(if res_id.is_empty() { &init_id } else { &res_id });
  812:         }
  813:         return o;
  814:     }
  815:     if !e.malformed.is_empty() {
  816:         fail(
  817:             &mut o,
  818:             &format!("malformed event stream: {}", e.malformed),
  819:             "transport",
  820:             &[],
  821:         );
  822:         o.thread_candidate = candidate_of(&init_id);
  823:         return o;
  824:     }
  825:     if e.init_count == 0 {
  826:         fail(&mut o, "the claude event stream has no init event - the turn's tools, MCP servers and permission mode are not proven", "permission", &[]);
  827:         return o;
  828:     }
  829:     if !e.has_result {
  830:         let why = format!(
  831:             "no result event in the claude event stream{}",
  832:             if stderr_tail.is_empty() {
  833:                 String::new()
  834:             } else {
  835:                 format!(" - {}", one_line(&stderr_tail))
  836:             }
  837:         );
  838:         fail(
  839:             &mut o,
  840:             &why,
  841:             evidence_class,
  842:             &[&quota_text, &auth_text, &stderr_tail],
  843:         );
  844:         o.thread_candidate = candidate_of(&init_id);
  845:         return o;
  846:     }
  847:     if !init_id.is_empty() && !res_id.is_empty() && init_id != res_id {
  848:         fail(
  849:             &mut o,
  850:             &format!("session id mismatch: init {init_id}, result {res_id}"),
---CHUNK---
  850:             &format!("session id mismatch: init {init_id}, result {res_id}"),
  851:             "unknown",
  852:             &[],
  853:         );
  854:         o.thread_candidate = candidate_of(&res_id);
  855:         return o;
  856:     }
  857:     if !expect.is_empty() && res_id != expect {
  858:         let why = if !turn.thread.is_empty() {
  859:             format!(
  860:                 "parent session {expect} not found, claude answered on {}",
  861:                 if res_id.is_empty() {
  862:                     "no session"
  863:                 } else {
  864:                     &res_id
  865:                 }
  866:             )
