 1067: 
 1068: /// `Read-ClaudeSalvage` (item 7): the assistant events' text blocks (messages) and thinking blocks
 1069: /// (reasoning) in stream order, the result's text when no text block came; a tool_use ->
 1070: /// `<tool>: <file_path | path | pattern>`, once per call id.
 1071: pub fn claude_salvage(events_text: &str) -> Salvage {
 1072:     let mut items: Vec<SalvageItem> = Vec::new();
 1073:     let mut tool_keys: Vec<String> = Vec::new();
 1074:     let mut tool_map: HashMap<String, String> = HashMap::new();
 1075:     let mut response = String::new();
 1076:     let mut saw_text = false;
 1077:     for line in events_text.split('\n') {
 1078:         let t = line.trim();
 1079:         if !t.starts_with('{') {
 1080:             continue;
 1081:         }
 1082:         let obj: Value = match serde_json::from_str(t) {
 1083:             Ok(v) => v,
 1084:             Err(_) => continue,
 1085:         };
 1086:         let ty = str_of(obj.get("type"));
 1087:         if ty == "result" {
 1088:             if let Some(s) = obj.get("result").and_then(|v| v.as_str()) {
 1089:                 response = s.to_string();
 1090:             }
 1091:             continue;
 1092:         }
 1093:         if ty != "assistant" {
 1094:             continue;
 1095:         }
 1096:         let content = obj
 1097:             .get("message")
 1098:             .and_then(|m| m.get("content"))
 1099:             .and_then(|c| c.as_array())
 1100:             .cloned()
 1101:             .unwrap_or_default();
 1102:         for b in content.iter().filter(|b| b.is_object()) {
 1103:             match str_of(b.get("type")).as_str() {
 1104:                 "text" => {
 1105:                     let tx = str_of(b.get("text"));
 1106:                     if !tx.trim().is_empty() {
 1107:                         items.push(SalvageItem {
 1108:                             kind: "message".into(),
 1109:                             text: tx,
 1110:                         });
 1111:                         saw_text = true;
 1112:                     }
 1113:                 }
 1114:                 "thinking" => {
 1115:                     let tx = str_of(b.get("thinking"));
 1116:                     if !tx.trim().is_empty() {
 1117:                         items.push(SalvageItem {
 1118:                             kind: "reasoning".into(),
 1119:                             text: tx,
 1120:                         });
 1121:                     }
 1122:                 }
 1123:                 "tool_use" => {
 1124:                     let mut id = str_of(b.get("id"));
 1125:                     if id.is_empty() {
 1126:                         id = format!("#{}", tool_keys.len());
 1127:                     }
 1128:                     let name = str_of(b.get("name"));
 1129:                     let mut target = String::new();
 1130:                     for f in ["file_path", "path", "pattern"] {
 1131:                         if let Some(s) = b
 1132:                             .get("input")
 1133:                             .and_then(|i| i.get(f))
 1134:                             .and_then(|v| v.as_str())
 1135:                         {
 1136:                             if !s.is_empty() {
 1137:                                 target = one_line(s);
 1138:                                 break;
 1139:                             }
 1140:                         }
 1141:                     }
 1142:                     if let std::collections::hash_map::Entry::Vacant(v) = tool_map.entry(id) {
 1143:                         tool_keys.push(v.key().clone());
 1144:                         v.insert(if target.is_empty() {
 1145:                             name
 1146:                         } else {
 1147:                             format!("{name}: {target}")
 1148:                         });
 1149:                     }
 1150:                 }
 1151:                 _ => {}
 1152:             }
 1153:         }
 1154:     }
 1155:     if !saw_text && !response.trim().is_empty() {
 1156:         items.push(SalvageItem {
 1157:             kind: "message".into(),
 1158:             text: response,
 1159:         });
 1160:     }
 1161:     Salvage {
 1162:         items,
 1163:         tools: tool_keys
 1164:             .iter()
 1165:             .filter_map(|k| tool_map.get(k).cloned())
 1166:             .collect(),
 1167:     }
 1168: }
