 1186: /// (wave 29) The claude branch of `Update-ToolFlight`: an assistant event's `tool_use` opens
 1187: /// `claude:<id>` (label `claude <name> <id>`), a user event's `tool_result` closes it.
 1188: pub fn claude_tool_flight(line: &str) -> ToolFlight {
 1189:     let t = line.trim();
 1190:     if !t.contains("tool_use") && !t.contains("tool_result") {
 1191:         return ToolFlight::None;
 1192:     }
 1193:     let obj: Value = match serde_json::from_str(t) {
 1194:         Ok(v) => v,
 1195:         Err(_) => return ToolFlight::None,
 1196:     };
 1197:     let ty = str_of(obj.get("type"));
 1198:     if ty != "assistant" && ty != "user" {
 1199:         return ToolFlight::None;
 1200:     }
 1201:     let content = obj
 1202:         .get("message")
 1203:         .and_then(|m| m.get("content"))
 1204:         .and_then(|c| c.as_array())
 1205:         .cloned()
 1206:         .unwrap_or_default();
 1207:     for b in content.iter().filter(|b| b.is_object()) {
 1208:         let bt = str_of(b.get("type"));
 1209:         if ty == "assistant" && bt == "tool_use" {
 1210:             let id = str_of(b.get("id"));
 1211:             if id.is_empty() {
 1212:                 continue;
 1213:             }
 1214:             let name = b
 1215:                 .get("name")
 1216:                 .and_then(|v| v.as_str())
 1217:                 .unwrap_or("tool")
 1218:                 .to_string();
 1219:             return ToolFlight::Open {
 1220:                 key: format!("claude:{id}"),
 1221:                 label: format!("claude {name} {id}"),
 1222:             };
 1223:         }
 1224:         if ty == "user" && bt == "tool_result" {
 1225:             let tid = str_of(b.get("tool_use_id"));
 1226:             if !tid.is_empty() {
 1227:                 return ToolFlight::Close {
 1228:                     key: format!("claude:{tid}"),
 1229:                     fallback_prefix: String::new(),
 1230:                 };
 1231:             }
 1232:         }
 1233:     }
 1234:     ToolFlight::None
 1235: }
