  1: //! The `claude` engine's credential side (plugin 0.6.0, wave 29 / 29b): THE child environment of
  2: //! every claude process (an ALLOW list; D2/D3), the launcher probes run in it
  3: //! (`Invoke-ClaudeProbe`: `claude auth status`, `claude --version`), the sign-in check
  4: //! (`Get-ClaudeSignIn`, its facts cached per launcher and auth - `$script:ClaudeSignInCache`), the
  5: //! local check no ledger evidence replaces (`Test-ClaudeLocalCredential`), the engine's credential
  6: //! for the preflight and the listing (`Get-EngineCredential`), the harness string
  7: //! (`Get-ClaudeHarness`) and the launch check (`Get-ClaudeLaunchProblem`). The turn itself is
  8: //! [`super::claude`].
  9: 
 10: use std::collections::HashMap;
 11: use std::path::{Path, PathBuf};
 12: use std::sync::{Mutex, OnceLock};
 13: use std::time::{Duration, Instant};
 14: 
 15: use serde_json::Value;
 16: 
 17: use c3_core::claude::{ChildEnv, ClaudeEndpoint, CLAUDE_AUTH_MODES};
 18: use c3_core::credential::CredentialResult;
 19: 
 20: fn one_line(s: &str) -> String {
 21:     c3_core::one_line(s)
 22: }
 23: 
 24: fn re(pat: &str) -> regex::Regex {
 25:     regex::Regex::new(pat).expect("a valid built-in regex")
 26: }
 27: 
 28: // --------------------------------------------------------------------------- the child environment
 29: 
 30: /// THE child environment of a claude process for `auth` (this process's environment, the test
 31: /// hook `CODEX_CONSULT_TEST_CHILD_ENV_PASS` in test mode, the endpoint's token read NOW).
 32: pub fn child_env(auth: &str, endpoint: Option<&ClaudeEndpoint>) -> ChildEnv {
 33:     let vars: Vec<(String, String)> = std::env::vars_os()
 34:         .filter_map(|(k, v)| Some((k.into_string().ok()?, v.into_string().ok()?)))
 35:         .collect();
 36:     let pass = c3_core::test_hooks::hook("CODEX_CONSULT_TEST_CHILD_ENV_PASS")
 37:         .map(|v| c3_core::claude::valid_pass_prefix(&v))
 38:         .unwrap_or_default();
 39:     let token = if auth == "endpoint" {
 40:         endpoint
 41:             .and_then(|ep| std::env::var(&ep.env_key).ok())
 42:             .filter(|v| !v.trim().is_empty())
 43:             .unwrap_or_default()
 44:     } else {
 45:         String::new()
 46:     };
 47:     c3_core::claude::child_environment(&vars, auth, endpoint, &pass, cfg!(windows), &token)
 48: }
 49: 
 50: /// A launcher probe's result (`Invoke-ClaudeProbe`).
 51: #[derive(Debug, Clone, Default)]
 52: pub struct Probe {
 53:     pub started: bool,
 54:     pub why: String,
 55:     pub exit: i32,
 56:     pub timed_out: bool,
 57:     pub out: String,
 58:     pub err: String,
 59: }
 60: 
 61: /// `Invoke-ClaudeProbe`: `<launcher> <args>` in the child environment of `auth` (D3), nothing on
 62: /// stdin, stdout and stderr as UTF-8, killed (its tree) after `timeout_sec`.
 63: pub fn probe(launcher: &str, args: &[&str], timeout_sec: u64, env: &ChildEnv) -> Probe {
 64:     use std::io::Read;
 65:     use std::process::{Command, Stdio};
 66:     let mut p = Probe {
 67:         exit: -1,
 68:         ..Default::default()
 69:     };
 70:     let mut cmd = Command::new(launcher);
 71:     cmd.args(args)
 72:         .env_clear()
 73:         .stdin(Stdio::null())
 74:         .stdout(Stdio::piped())
 75:         .stderr(Stdio::piped());
 76:     for (k, v) in &env.env {
 77:         cmd.env(k, v);
 78:     }
 79:     let mut child = match cmd.spawn() {
 80:         Ok(c) => c,
 81:         Err(e) => {
 82:             p.why = one_line(&e.to_string());
 83:             return p;
 84:         }
 85:     };
 86:     p.started = true;
 87:     let mut out = child.stdout.take().expect("piped");
 88:     let mut err = child.stderr.take().expect("piped");
 89:     let oh = std::thread::spawn(move || {
 90:         let mut b = Vec::new();
 91:         let _ = out.read_to_end(&mut b);
 92:         String::from_utf8_lossy(&b).to_string()
 93:     });
 94:     let eh = std::thread::spawn(move || {
 95:         let mut b = Vec::new();
 96:         let _ = err.read_to_end(&mut b);
 97:         String::from_utf8_lossy(&b).to_string()
 98:     });
 99:     let start = Instant::now();
100:     loop {
101:         match child.try_wait() {
102:             Ok(Some(status)) => {
103:                 p.exit = status.code().unwrap_or(-1);
104:                 p.out = oh.join().unwrap_or_default();
105:                 p.err = eh.join().unwrap_or_default();
106:                 return p;
107:             }
108:             Ok(None) => {
109:                 if start.elapsed() >= Duration::from_secs(timeout_sec) {
110:                     super::subprocess::kill_tree_by_pid(child.id());
111:                     let _ = child.kill();
112:                     let _ = child.wait();
113:                     p.timed_out = true;
114:                     return p;
115:                 }
116:                 std::thread::sleep(Duration::from_millis(50));
117:             }
118:             Err(e) => {
119:                 p.why = one_line(&e.to_string());
120:                 return p;
121:             }
122:         }
123:     }
124: }
125: 
126: /// What `claude auth status` reported in this process (`$script:ClaudeSignInCache`): only
127: /// authMethod, apiProvider and projectsDirectory - never the account's e-mail or organisation.
128: #[derive(Debug, Clone, Default)]
129: pub struct SignInInfo {
130:     pub auth_method: String,
131:     pub api_provider: String,
132:     pub projects_directory: String,
133: }
134: 
135: fn sign_in_cache() -> &'static Mutex<HashMap<String, (SignInInfo, CredentialResult)>> {
136:     static C: OnceLock<Mutex<HashMap<String, (SignInInfo, CredentialResult)>>> = OnceLock::new();
137:     C.get_or_init(|| Mutex::new(HashMap::new()))
138: }
139: 
140: /// The cached `claude auth status` facts of `launcher|auth` (`None` when it did not run).
141: pub fn sign_in_info(launcher: &str, auth: &str) -> Option<SignInInfo> {
142:     sign_in_cache()
143:         .lock()
144:         .ok()?
145:         .get(&format!("{launcher}|{auth}"))
146:         .map(|(i, _)| i.clone())
147: }
148: 
149: /// `Test-ClaudeLocalCredential`: the local part of a claude entry's sign-in that no ledger evidence
150: /// replaces - auth api-key: `ANTHROPIC_API_KEY` set now; auth endpoint: a usable endpoint and its
151: /// token variable set now. `""` or the reason (a name, never a value).
152: pub fn local_credential(auth: &str, endpoint: Option<&ClaudeEndpoint>) -> String {
153:     if auth == "endpoint" {
154:         let ep = c3_core::claude::endpoint_problem(endpoint);
155:         if !ep.is_empty() {
156:             return ep;
157:         }
158:         let e = endpoint.expect("checked");
159:         let set = std::env::var(&e.env_key)
160:             .map(|v| !v.trim().is_empty())
161:             .unwrap_or(false);
162:         if !set {
163:             return format!("env {} not set", e.env_key);
164:         }
165:         return String::new();
166:     }
167:     if auth != "api-key" {
168:         return String::new();
169:     }
170:     let set = std::env::var("ANTHROPIC_API_KEY")
171:         .map(|v| !v.trim().is_empty())
172:         .unwrap_or(false);
173:     if set {
174:         String::new()
175:     } else {
176:         "ANTHROPIC_API_KEY is not set (roster auth api-key)".to_string()
177:     }
178: }
179: 
180: /// `Get-ClaudeSignIn`: `claude auth status` (local, free) in the child environment of `auth`,
181: /// its JSON read BEFORE its exit code; auth endpoint: no probe - the endpoint and its token
182: /// variable (`ok: env <NAME> set`). One probe per `launcher|auth` per process.
183: pub fn sign_in(
184:     launcher: &str,
185:     timeout_sec: u64,
186:     auth: &str,
187:     endpoint: Option<&ClaudeEndpoint>,
188: ) -> CredentialResult {
189:     let auth = if CLAUDE_AUTH_MODES.contains(&auth) {
190:         auth
191:     } else {
192:         "subscription"
193:     };
194:     if launcher.is_empty() {
195:         return CredentialResult::missing("claude CLI not found on PATH");
196:     }
197:     if auth == "endpoint" {
198:         let ep = c3_core::claude::endpoint_problem(endpoint);
199:         if !ep.is_empty() {
200:             return CredentialResult::missing(ep);
201:         }
202:         let e = endpoint.expect("checked");
203:         let set = std::env::var(&e.env_key)
204:             .map(|v| !v.trim().is_empty())
205:             .unwrap_or(false);
206:         if !set {
207:             return CredentialResult::missing(format!("env {} not set", e.env_key));
208:         }
209:         return CredentialResult::ok(format!("env {} set", e.env_key));
210:     }
211:     if auth == "api-key" {
212:         let w = local_credential(auth, endpoint);
213:         if !w.is_empty() {
214:             return CredentialResult::missing(w);
215:         }
216:     }
217:     let key = format!("{launcher}|{auth}");
218:     if let Some((_, r)) = sign_in_cache()
219:         .lock()
220:         .ok()
221:         .and_then(|c| c.get(&key).cloned())
222:     {
223:         return r;
224:     }
225:     let t = if timeout_sec > 0 {
226:         timeout_sec.min(15)
227:     } else {
228:         15
229:     };
230:     let env = child_env(auth, None);
231:     let cap = probe(launcher, &["auth", "status"], t, &env);
232:     if !cap.started {
233:         return CredentialResult::unknown(format!(
234:             "not checked - `claude auth status` could not be started{}",
235:             if cap.why.is_empty() {
236:                 String::new()
237:             } else {
238:                 format!(" ({})", cap.why)
239:             }
240:         ));
241:     }
242:     if cap.timed_out {
243:         return CredentialResult::unknown(format!(
244:             "not checked - `claude auth status` did not finish within {t} s"
245:         ));
246:     }
247:     let out = cap.out.clone();
248:     let obj: Option<Value> = match (out.find('{'), out.rfind('}')) {
249:         (Some(a), Some(b)) if b > a => serde_json::from_str(&out[a..=b]).ok(),
250:         _ => None,
251:     };
252:     let Some(o) = obj.filter(|v| v.is_object()) else {
253:         return CredentialResult::unknown(format!(
254:             "not checked - `claude auth status` printed no JSON object (exit {})",
255:             cap.exit
256:         ));
257:     };
258:     let li = o.get("loggedIn").and_then(|v| v.as_bool());
259:     let am = c3_core::claude::token(o.get("authMethod"));
260:     let ap = c3_core::claude::token(o.get("apiProvider"));
261:     let pd = o
262:         .get("projectsDirectory")
263:         .and_then(|v| v.as_str())
264:         .unwrap_or("")
265:         .to_string();
266:     let info = SignInInfo {
267:         auth_method: am.clone(),
268:         api_provider: ap.clone(),
269:         projects_directory: pd,
270:     };
271:     let result = if li == Some(false) {
272:         CredentialResult::missing(
273:             "not signed in (`claude auth status`: loggedIn false; run `claude auth login`)",
274:         )
275:     } else if li != Some(true) {
276:         CredentialResult::unknown(format!(
277:             "not checked - `claude auth status` names no loggedIn (exit {})",
278:             cap.exit
279:         ))
280:     } else if !ap.is_empty() && ap != "firstParty" {
281:         CredentialResult::missing(format!("apiProvider {ap} - routes other than Anthropic's own API (a gateway, Bedrock, Vertex, Foundry) are out of scope for the claude engine"))
282:     } else if auth == "subscription" {
283:         if am != "claude.ai" {
284:             CredentialResult::missing(format!("signed in with authMethod {}, not the claude.ai subscription the roster names (auth subscription; an API key is auth api-key)", if am.is_empty() { "(none)" } else { &am }))
285:         } else {
286:             CredentialResult::ok("signed in (claude.ai subscription)")
287:         }
288:     } else {
289:         CredentialResult::ok(format!(
290:             "signed in (ANTHROPIC_API_KEY set{})",
291:             if am.is_empty() {
292:                 String::new()
293:             } else {
294:                 format!("; authMethod {am}")
295:             }
296:         ))
297:     };
298:     if let Ok(mut c) = sign_in_cache().lock() {
299:         c.insert(key, (info, result.clone()));
300:     }
301:     result
302: }
303: 
304: /// `Get-EngineCredential` for the claude engine (the preflight and the listing): no launcher ->
305: /// missing; the LOCAL check that no ledger evidence replaces (auth api-key: `ANTHROPIC_API_KEY`
306: /// set now; auth endpoint: the endpoint and its token variable); auth endpoint is checked locally
307: /// every time (`ok: env <NAME> set` - no `claude auth status`, under `-NoNetwork` too); then a
308: /// usable reply of this endpoint within 60 minutes evidences the sign-in; `-NoNetwork` (the
309: /// SessionStart hook) starts nothing; else `claude auth status` (`CODEX_CONSULT_TEST_LOGIN_TIMEOUT`
310: /// shortens the 15 s in test mode).
311: pub fn engine_credential(
312:     launcher: &str,
313:     auth: &str,
314:     endpoint: Option<&ClaudeEndpoint>,
315:     health: Option<&c3_core::health::EndpointHealth>,
316:     no_network: bool,
317: ) -> CredentialResult {
318:     let auth = if CLAUDE_AUTH_MODES.contains(&auth) {
319:         auth
320:     } else {
321:         "subscription"
322:     };
323:     if launcher.is_empty() {
324:         return CredentialResult::missing("claude CLI not found on PATH");
325:     }
326:     let local = local_credential(auth, endpoint);
327:     if !local.is_empty() {
328:         return CredentialResult::missing(local);
329:     }
330:     if auth == "endpoint" {
331:         return sign_in(launcher, 0, auth, endpoint);
332:     }
333:     if let Some(ru) = health.and_then(|h| h.recent_usable.as_ref()) {
334:         return CredentialResult::ok(format!(
335:             "signed in (usable reply {} min ago)",
336:             ru.age_minutes
337:         ));
338:     }
339:     if no_network {
340:         return CredentialResult::with_detail(
341:             c3_core::credential::State::Unknown,
342:             "sign-in not checked",
343:             "not checked (launcher present; run codex-providers.ps1)",
344:         );
345:     }
346:     let mut timeout = 45u64;
347:     if let Some(hook) = c3_core::test_hooks::hook("CODEX_CONSULT_TEST_LOGIN_TIMEOUT") {
348:         if let Ok(n) = hook.trim().parse::<u64>() {
349:             if n > 0 {
350:                 timeout = n;
351:             }
352:         }
353:     }
354:     sign_in(launcher, timeout, auth, None)
355: }
356: 
357: /// `Get-ClaudeLaunchProblem` (item 2): where the engine keeps its transcripts must not lie in the
358: /// repository under review - `CLAUDE_CONFIG_DIR`, and the projectsDirectory the sign-in reported.
359: pub fn launch_problem(repo_root: &Path, launcher: &str, auth: &str) -> String {
360:     let inside = |p: &str| -> bool {
361:         let pb = PathBuf::from(p.trim());
362:         let full = if pb.is_absolute() {
363:             pb
364:         } else {
365:             std::env::current_dir().unwrap_or_default().join(pb)
366:         };
367:         c3_core::paths::repo_relative(repo_root, &full).is_some()
368:     };
369:     if let Ok(cfg) = std::env::var("CLAUDE_CONFIG_DIR") {
370:         if !cfg.trim().is_empty() && inside(&cfg) {
371:             return format!("CLAUDE_CONFIG_DIR ({}) lies inside the repository under review: the engine's transcripts would change the tree; point it elsewhere", cfg.trim());
372:         }
373:     }
374:     if let Some(info) = sign_in_info(launcher, auth) {
375:         let pd = info.projects_directory.trim().to_string();
376:         if !pd.is_empty() && inside(&pd) {
377:             return format!("the claude projectsDirectory ({pd}) lies inside the repository under review: the engine's transcripts would change the tree");
378:         }
379:     }
380:     String::new()
381: }
382: 
383: /// `Get-ClaudeHarness`: `claude-cli <version>` from `<launcher> --version` in the child
384: /// environment (15 s; the launcher's file metadata is not read by c3), else
385: /// `claude-cli (version unknown)`. Cached per launcher.
386: pub fn harness(launcher: &str) -> String {
387:     static C: OnceLock<Mutex<HashMap<String, String>>> = OnceLock::new();
388:     let cache = C.get_or_init(|| Mutex::new(HashMap::new()));
389:     if launcher.is_empty() {
390:         return "claude-cli (version unknown)".to_string();
391:     }
392:     if let Some(h) = cache.lock().ok().and_then(|c| c.get(launcher).cloned()) {
393:         return h;
394:     }
395:     let ver_re = re(r"^v?[0-9]+\.[0-9]+[0-9A-Za-z.+_-]{0,48}$");
396:     let mut ver = String::new();
397:     let cap = probe(
398:         launcher,
399:         &["--version"],
400:         15,
401:         &child_env("subscription", None),
402:     );
403:     if cap.started && !cap.timed_out && cap.exit == 0 {
404:         for tok in format!("{}\n{}", cap.out, cap.err).split_whitespace() {
405:             if ver_re.is_match(tok) {
406:                 ver = tok.to_string();
407:                 break;
408:             }
409:         }
410:     }
411:     let h = if ver.is_empty() {
412:         "claude-cli (version unknown)".to_string()
413:     } else {
414:         format!("claude-cli {}", ver.trim_start_matches('v'))
415:     };
416:     if let Ok(mut c) = cache.lock() {
417:         c.insert(launcher.to_string(), h.clone());
418:     }
419:     h
420: }

